  "hypothesis": "Replacing the fixed mixture grid with an adaptive, kink-aware scalar search will find improving packet remeshings that the five original mixture weights miss.",
  "rationale": "The incumbent is reported to lie at a kink of the exact objective, so useful mixtures may occupy very narrow intervals or require weights much smaller than 0.0078125. The convolution remains quadratic along each mixture, allowing its integrated-square numerator to be evaluated as a quartic while adaptively refining the mixture weight; every accepted result is still checked with the frozen verifier formula.",
  "source": "import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve
from scipy.optimize import minimize_scalar

PARAMS = {
    'proposals': (24, 6, 64),
    'width_step': (1.0, 0.25, 8.0),
    'reserve': (0.70, 0.5, 0.75)
}

def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['reserve']) * budget_s
    rng = np.random.default_rng(seed)
    def alive(margin=0.0):
        return time.monotonic() + margin < deadline
    def exact(f):
        f = np.maximum(f, 0.0)
        c = oaconvolve(f, f, mode='full')
        m = len(c)
        dx = np.diff(np.linspace(-0.5, 0.5, m + 2))
        y = np.concatenate(([0.0], c, [0.0]))
        num = float(np.sum((dx / 3.0) * (y[:-1]**2 + y[:-1]*y[1:] + y[1:]**2)))
        return num / ((np.sum(np.abs(c))/(m+1))*np.max(np.abs(c)))
    if init is None:
        return {'values': [1.0]}
    if 'values' in init:
        raw = init['values']
    else:
        raw = np.zeros(int(init['length']))
        for a, v in init['packets']:
            if not alive(3):
                return init
            raw[int(a):int(a)+len(v)] += np.asarray(v)
    f = np.maximum(np.asarray(raw, dtype=np.float64), 0.0)
    baseline = exact(f)
    if not alive(5) or len(f) < 4:
        return init
    n = len(f)
    f = f / np.max(f)
    edges = np.diff(np.r_[False, f > 0, False].astype(np.int8))
    aa = np.flatnonzero(edges == 1)
    bb = np.flatnonzero(edges == -1)
    if len(aa) < 2:
        return init
    mass = np.r_[0.0, np.cumsum(f)]
    heavy = int(np.argmax(mass[bb]-mass[aa]))
    prefixes = []
    for a, b in zip(aa, bb):
        if not alive(5):
            return init
        prefixes.append(np.r_[0.0, np.cumsum(f[a:b])])
    nc = 2*n-1
    L = next_fast_len(nc)
    F = rfft(f, L, workers=1)
    c = irfft(F*F, L, workers=1)[:nc]
    def bilinear(x, y):
        return float(2*np.dot(x, y) + 0.5*np.dot(x[:-1], y[1:]) + 0.5*np.dot(x[1:], y[:-1]))
    q0 = bilinear(c, c)
    best_score = baseline
    best = None
    step = float(params['width_step'])
    specs = []
    for delta in (step, -step, 2*step, -2*step, 4*step, -4*step):
        for anchor in (0.5, 0.0, 1.0):
            if not alive(4):
                return init
            specs.append((delta, anchor, 0))
    specs += [(step,0.5,1),(-step,0.5,1),(2*step,0.5,2),(-2*step,0.5,2),(.20,0.5,3),(-.20,0.5,3)]
    for j in range(max(0, int(params['proposals'])-len(specs))):
        if not alive(5):
            break
        specs.append((float(rng.choice([-1,1]))*step*float(rng.uniform(.5,5)), float(rng.choice([0,.5,1])), int(rng.integers(0,3))))
    for delta, anchor, mode in specs[:int(params['proposals'])]:
        if not alive(5):
            break
        g = np.zeros(n, dtype=np.float64)
        complete = True
        for j, (a,b) in enumerate(zip(aa,bb)):
            if not alive(4):
                complete = False
                break
            a,b = int(a),int(b)
            w = b-a
            if j == heavy:
                g[a:b] += f[a:b]
                continue
            x = (a+b)/(2.0*n)
            if mode == 1:
                change = delta*(2*x-1)
            elif mode == 2:
                change = delta*np.cos(2*np.pi*x)
            elif mode == 3:
                change = delta*w
            else:
                change = delta
            new_w = max(0.25,w+change)
            left = a-anchor*(new_w-w)
            right = left+new_w
            if left < 0:
                right -= left
                left = 0.0
            if right > n:
                left -= right-n
                right = float(n)
            left = max(0.0,left)
            actual = right-left
            if actual <= 0:
                complete = False
                break
            lo = max(0,int(np.floor(left)))
            hi = min(n,int(np.ceil(right)))
            boundaries = np.arange(lo,hi+1,dtype=np.float64)
            old_coordinate = np.clip((boundaries-left)*(w/actual),0.0,float(w))
            ix = np.minimum(np.floor(old_coordinate).astype(np.int64),w-1)
            integral = prefixes[j][ix] + (old_coordinate-ix)*f[a+ix]
            g[lo:hi] += np.maximum(np.diff(integral),0.0)
        if not complete or not alive(4):
            break
        d = g-f
        D = rfft(d,L,workers=1)
        cd = 2*irfft(F*D,L,workers=1)[:nc]
        dd = irfft(D*D,L,workers=1)[:nc]
        if not alive(3):
            break
        # Exact quartic numerator for c(alpha)=c+alpha*cd+alpha^2*dd.
        q = [q0, 2*bilinear(c,cd), bilinear(cd,cd)+2*bilinear(c,dd), 2*bilinear(cd,dd), bilinear(dd,dd)]
        winner = [0.0, best_score]
        cache = {}
        def score_alpha(alpha):
            alpha = float(alpha)
            if alpha in cache:
                return cache[alpha]
            if not alive(2.5):
                return -1.0
            cc = c + alpha*cd + (alpha*alpha)*dd
            numerator = ((((q[4]*alpha+q[3])*alpha+q[2])*alpha+q[1])*alpha+q[0])
            denominator = 3*float(np.sum(np.abs(cc)))*float(np.max(np.abs(cc)))
            score = numerator/denominator
            cache[alpha] = score
            if score > winner[1] + 2e-13:
                winner[:] = [alpha, score]
            return score
        # Logarithmic screening includes much smaller mixtures than the parent.
        samples = []
        for k in range(9):
            if not alive(3):
                break
            alpha = 8.0**(-k)
            samples.append((alpha, score_alpha(alpha)))
        if samples and alive(3):
            idx = max(range(len(samples)), key=lambda i: samples[i][1])
            # Refine around the best screened scale, including maxima caused
            # by a change in which convolution lag attains the peak.
            lo = samples[min(idx+1,len(samples)-1)][0]/8.0
            hi = samples[max(0,idx-1)][0]
            if hi > lo:
                def objective(t):
                    return -score_alpha(np.exp(t))
                minimize_scalar(objective, bounds=(np.log(lo),np.log(hi)), method='bounded', options={'maxiter': 12, 'xatol': 0.002})
        if winner[0] > 0 and alive(2.5):
            proposal = np.maximum(f+winner[0]*d,0.0)
            verified = exact(proposal)
            if verified > best_score:
                best_score = verified
                best = proposal
    if best is None:
        return init
    transitions = np.diff(np.r_[False,best > 0,False].astype(np.int8))
    starts = np.flatnonzero(transitions == 1)
    stops = np.flatnonzero(transitions == -1)
    packets = []
    for a,b in zip(starts,stops):
        if time.monotonic() > start + .90*budget_s:
            return init
        packets.append([int(a),best[a:b].tolist()])
    return {'length': n, 'packets': packets}
